package com.saristore.dao;
import com.saristore.config.DatabaseConfig;import com.saristore.model.Customer;import java.math.BigDecimal;import java.sql.*;import java.util.*;
public class CustomerDAO {
 public List<Customer> all()throws SQLException{try(Connection c=DatabaseConfig.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM customers ORDER BY name");ResultSet r=p.executeQuery()){List<Customer> a=new ArrayList<>();while(r.next())a.add(new Customer(r.getInt("id"),r.getString("name"),r.getString("phone"),r.getString("address"),r.getBigDecimal("current_debt")));return a;}}
 public int create(String name,String phone,String address)throws SQLException{try(Connection c=DatabaseConfig.connect();PreparedStatement p=c.prepareStatement("INSERT INTO customers(name,phone,address) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,phone);p.setString(3,address);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getInt(1);}}}
 public void repay(int customerId,BigDecimal amount)throws SQLException{if(amount.signum()<=0)throw new SQLException("Payment must be greater than zero.");try(Connection c=DatabaseConfig.connect()){c.setAutoCommit(false);try(PreparedStatement q=c.prepareStatement("SELECT current_debt FROM customers WHERE id=? FOR UPDATE")){q.setInt(1,customerId);try(ResultSet r=q.executeQuery()){if(!r.next())throw new SQLException("Customer not found");if(amount.compareTo(r.getBigDecimal(1))>0)throw new SQLException("Payment exceeds outstanding balance");}}try(PreparedStatement p=c.prepareStatement("UPDATE customers SET current_debt=current_debt-? WHERE id=?");PreparedStatement i=c.prepareStatement("INSERT INTO credit_payments(customer_id,amount_paid) VALUES(?,?)")){p.setBigDecimal(1,amount);p.setInt(2,customerId);p.executeUpdate();i.setInt(1,customerId);i.setBigDecimal(2,amount);i.executeUpdate();}c.commit();}catch(SQLException e){throw e;}}
}